import 'package:flutter/material.dart';import 'package:sehatak/core/models/child/child_models.dart';import 'package:sehatak/core/services/child_service.dart';class ChildClinicDetailScreen extends StatelessWidget{final String clinicId;const ChildClinicDetailScreen({super.key,required this.clinicId});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('تفاصيل عيادة الأطفال')),body:FutureBuilder<List<ChildClinic>>(future:ChildService().streamClinics(limit:50).first,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final x=s.data!.where((e)=>e.id==clinicId);if(x.isEmpty)return const Center(child:Text('العيادة غير موجودة'));final d=x.first;return ListView(padding:const EdgeInsets.all(20),children:[const Icon(Icons.local_hospital,size:70,color:Color(0xFF00BCD4)),Text(d.name,textAlign:TextAlign.center,style:const TextStyle(fontSize:22,fontWeight:FontWeight.w800)),Text(d.type,textAlign:TextAlign.center),Text('العنوان: ${d.address}'),Text('الهاتف: ${d.phone}'),Text('التقييم: ${d.rating.toStringAsFixed(1)}')]);}));}}
